function openSearch(){modalOpen('Search the course',`<label class="field-label" for="course-search">Tutorials, homework, SQL questions, and glossary</label><input id="course-search" type="search" placeholder="Try Cosmos, Parquet, or SELECT…"><div id="search-results" class="mt" aria-live="polite"><p>Enter a topic to find relevant materials.</p></div>`);$('#course-search').focus()}
function search(value){const q=value.trim().toLowerCase();if(!q){$('#search-results').innerHTML='<p>Enter a topic to find relevant materials.</p>';return}const matches=[...C.items.map(i=>({title:i.title,text:i.markdown,url:linkFor(i),kind:i.kind})),...C.exercises.map(x=>({title:x.group+' SQL '+x.number,text:x.question,url:'#practice/'+x.id,kind:'Practice'})),...C.glossary.map((g,n)=>({title:g.term,text:g.definition,url:'#glossary/'+encodeURIComponent(g.term),kind:'Glossary'}))].map(x=>({...x,text:x.text.replace(/<[^>]+>/g,' ').replace(/!?\[([^\]]+)\]\([^)]+\)/g,'$1').replace(/[#*`]/g,'')})).filter(x=>(x.title+' '+x.text).toLowerCase().includes(q)).sort((a,b)=>Number(b.title.toLowerCase().includes(q))-Number(a.title.toLowerCase().includes(q))).slice(0,30);$('#search-results').innerHTML=matches.length?matches.map(x=>{const pos=Math.max(0,x.text.toLowerCase().indexOf(q)-40);return `<a class="search-result" data-close="true" href="${x.url}">${icon('search')}<div><strong>${esc(x.title)}</strong><small>${esc(x.kind)} · ${esc(x.text.slice(pos,pos+140).replace(/[#*`]/g,''))}…</small></div></a>`}).join(''):'<p>No results. Try a shorter or different term.</p>';icons()}
const currentItem=()=>item(location.hash.split('/')[1]);
function render(focus=false){const token=++routeId,[view='overview',id]=location.hash.slice(1).split('/');delete main.dataset.thread;$$('[data-nav]').forEach(a=>{a.removeAttribute('aria-current');if(a.dataset.nav===(view==='thread'?'discuss':view==='notebook'?'practice':view))a.setAttribute('aria-current','page')});const i=item(id);main.innerHTML=view==='learn'?(i&&i.kind==='lesson'?lesson(i):learnIndex()):view==='homework'?homework(i?.kind==='homework'?i:null):view==='practice'?practice(id):view==='notebook'?notebook(id):view==='resources'?resources():view==='glossary'?glossary(id?decodeURIComponent(id):''):view==='discuss'?discuss(i?id:'general'):view==='account'?account():view==='thread'?'<p role="status">Loading…</p>':overview();icons();if(view==='discuss')loadDiscussions(i?id:'general',token);if(view==='thread')loadThread(id,token);document.title=(i?i.title:({overview:'Overview',learn:'Learn',practice:'SQL lab',notebook:'SQL notebook',homework:'Homework',discuss:'Discussion',thread:'Discussion',resources:'Resources',glossary:'Glossary',account:'My workspace'}[view]||'Course'))+' · Data at Scale';if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}}
async function action(button){const a=button.dataset.action,id=button.dataset.id,i=item(id);switch(a){case'journey':$('#journey-content').innerHTML=journey(Number(button.dataset.journey));$$('[data-journey]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));icons();break;case'close':modal.close();break;case'search':openSearch();break;case'notes':openNotes(id);break;case'refresh':render();break;case'print':window.print();break;case'bookmark':save('bookmarks',id,!get('bookmarks',id));render();break;case'lesson-tab':save('progress',id,{...progress(id),tab:button.dataset.tab});render();$('#tab-'+button.dataset.tab)?.focus({preventScroll:true});break;case'step':save('progress',id,{...progress(id),step:Number(button.dataset.step),tab:'steps'});render();$('#lesson-content').scrollIntoView({block:'start',behavior:'smooth'});break;case'answer':save('progress',id,{...progress(id),answer:Number(button.dataset.choice)});render();$(`[data-choice="${button.dataset.choice}"]`)?.focus({preventScroll:true});break;case'complete':save('progress',id,{...progress(id),completed:true});render();toast('Marked complete. Your progress is saved.');break;
case'learning-stage':{const descriptions=['Before following commands, explain the purpose of the resource you are creating. Connect it to what you learned in the previous lesson.','Follow one guided step at a time in your own Azure workspace. Copy commands carefully, replacing placeholders with your actual resource names.','Inspect actual results and compare them with the instructions. Use the concept check to test your understanding, then record what you learned.'];$$('.flow-node').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));$('#stage-detail').innerHTML=icon('lightbulb')+'<p>'+descriptions[Number(button.dataset.stage)]+'</p>';icons();break}
case'copy-code':{const code=$('code',button.parentElement)?.textContent||'';try{await navigator.clipboard.writeText(code);button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1500)}catch{toast('Select the code and copy it using your keyboard.')}break}
case'run-sql':{const ex=C.exercises.find(x=>x.id===id),query=$('#sql-editor').value,token=routeId;save('sql',id,{...get('sql',id,{}),query});button.disabled=true;$('#sql-feedback').textContent='Running your query…';try{const result=await runQuery(query);if(routeId!==token)break;const ok=resultsEqual(result,ex.expected,ex.ordered);$('#sql-results').innerHTML=resultTable(result);$('#sql-feedback').innerHTML=ok?'<strong>Correct result.</strong> Your query returns the expected rows.':'<strong>Keep going.</strong> Compare the requested columns, filters, grouping, and '+(ex.ordered?'row order.':'row values.');if(ok){save('sql',id,{...get('sql',id,{}),query,solved:true});toast('Exercise solved. Your progress is saved.')}}catch(e){if(routeId===token){$('#sql-feedback').innerHTML='<span class="error">'+esc(e.message)+'</span>';$('#sql-results').innerHTML=''}}finally{if(routeId===token)button.disabled=false}break}
case'sql-hint':{const ex=C.exercises.find(x=>x.id===id);$('#sql-assistance').innerHTML=`<div class="hint">${esc(ex.hint)}</div>`;break}
case'sql-solution':{const ex=C.exercises.find(x=>x.id===id);save('sql',id,{...get('sql',id,{}),viewed:true});$('#sql-assistance').innerHTML=`<div class="hint"><strong>Reference solution</strong><p>Compare the structure with your attempt. Then close it and try writing the query again.</p>${article('```sql\n'+ex.solution+'\n```')}<button class="text-button" data-action="hide-assistance">Hide solution</button></div>`;break}
case'hide-assistance':$('#sql-assistance').innerHTML='';break;case'sql-reset':save('sql',id,{...get('sql',id,{}),query:'SELECT \nFROM Products;'});render();break;
case'preview-table':{button.disabled=true;try{const name=button.dataset.table;if(!['Products','Sales'].includes(name))break;const result=await runQuery('SELECT * FROM '+name);modalOpen(name,resultTable(result))}finally{button.disabled=false}break}
case'new-thread':threadForm(id);break;case'edit-thread':threadForm(JSON.parse(main.dataset.thread).lesson,JSON.parse(main.dataset.thread));break;
case'thread-status':await api('threads/'+id,'PUT',{status:button.dataset.status});render();break;
case'delete-thread':modalOpen('Remove this discussion?',`<p>The discussion will no longer appear in the course conversation.</p><button class="primary" data-action="confirm-delete-thread" data-id="${id}" data-lesson="${button.dataset.lesson}">Remove discussion</button>`);break;
case'confirm-delete-thread':await api('threads/'+id,'PUT',{deleted:true});modal.close();location.hash='#discuss/'+button.dataset.lesson;break;
case'delete-reply':modalOpen('Remove this reply?',`<p>Your reply will no longer appear in this discussion.</p><button class="primary" data-action="confirm-delete-reply" data-id="${id}">Remove reply</button>`);break;
case'confirm-delete-reply':await api('replies/'+id,'DELETE',{});modal.close();render();break;
case'report-thread':modalOpen('Report a discussion or reply',`<form id="report-form" data-id="${id}"><label class="field-label" for="report-reason">What should the moderator review?</label><textarea id="report-reason" name="reason" minlength="5" maxlength="500" required placeholder="If reporting a reply, identify it by author and time."></textarea><button class="primary mt" type="submit">Send report</button><p class="form-feedback error" role="status"></p></form>`);break;
case'export':{const blob=new Blob([JSON.stringify({course:'DX604 Module 4',exportedAt:new Date().toISOString(),records:state.records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='data-at-scale-my-work.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);break}
case'import':$('#import-file').click();break;
case'confirm-import':if(stagedImport){for(const [area,records] of Object.entries(stagedImport))for(const [key,value] of Object.entries(records))(state.records[area]??={})[key]=value;persist();stagedImport=null;modal.close();render();toast('Backup imported into this browser.')}break;
case'reset-work':modalOpen('Reset private study work?',`<p>This removes your notes, SQL attempts, bookmarks, checklist, and progress from this browser. Export your work first if you want to keep it.</p><div class="row"><button class="secondary" data-action="export">Export first</button><button class="primary" data-action="confirm-reset">Reset private work</button></div>`);break;
case'confirm-reset':state={records:{}};persist();modal.close();render();toast('Private study work reset.');break;
}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();if(b.disabled)return;try{await action(b)}catch(err){toast(err.message)}return}const img=e.target.closest('[data-image]');if(img){modalOpen('Tutorial screenshot',`<img class="expanded-screenshot" src="${esc(img.dataset.image)}" alt="${esc(img.dataset.alt)}"><p>${ext(img.dataset.image,'Open full-size image')}</p>`);return}const anchor=e.target.closest('[data-anchor]');if(anchor){e.preventDefault();(document.getElementById(anchor.dataset.anchor)||document.getElementById(anchor.dataset.anchor.toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu,'').trim().replace(/\s+/g,'-')))?.scrollIntoView();return}if(e.target.closest('[data-close]'))modal.close();if(e.target.closest('.skip')){e.preventDefault();main.focus()}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='course-search')search(el.value);if(el.id==='note-text')save('notes',$('#note-lesson').value,el.value);if(el.id==='sql-editor')save('sql',el.dataset.exercise,{...get('sql',el.dataset.exercise,{}),query:el.value});if(el.id==='glossary-filter'){const q=el.value.toLowerCase();$$('[data-term]').forEach(x=>x.hidden=!x.dataset.term.includes(q));$('#glossary-empty').hidden=$$('[data-term]').some(x=>!x.hidden)}if(el.id==='lesson-filter'){const q=el.value.toLowerCase();$$('.lesson-group .course-lesson').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q));$$('.lesson-group').forEach(x=>x.hidden=!$$('.course-lesson',x).some(a=>!a.hidden))}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='notebook-section')location.hash='#notebook/'+el.value;if(el.id==='exercise-select')location.hash='#practice/'+el.value;if(el.id==='discussion-filter')location.hash='#discuss/'+el.value;if(el.id==='note-lesson')$('#note-text').value=get('notes',el.value,'');if(el.dataset.hw){save('homework',el.dataset.hw,{...get('homework',el.dataset.hw,{}),[el.dataset.key]:el.checked});const y=window.scrollY;render();window.scrollTo(0,y);$(`[data-hw="${el.dataset.hw}"][data-key="${el.dataset.key}"]`)?.focus({preventScroll:true})}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['thread-form','reply-form','report-form'].includes(f.id))return;e.preventDefault();const b=$('[type=submit]',f),data=Object.fromEntries(new FormData(f));b.disabled=true;$('.form-feedback',f).textContent='';try{if(f.id==='thread-form'){const res=await api('threads'+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PUT':'POST',data);modal.close();location.hash='#thread/'+(f.dataset.id||res.id);render()}if(f.id==='reply-form'){await api('threads/'+f.dataset.id+'/replies','POST',data);render();toast('Reply posted.')}if(f.id==='report-form'){await api('threads/'+f.dataset.id+'/report','POST',data);modal.close();toast('Report recorded.')}}catch(err){$('.form-feedback',f).textContent=err.message}finally{b.disabled=false}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('Choose a study backup smaller than 1 MB.');const backup=JSON.parse(await file.text());if(backup.course!=='DX604 Module 4'||!backup.records||typeof backup.records!=='object'||Array.isArray(backup.records))throw Error('This file is not a Data at Scale study backup.');const records={},allowed=['progress','notes','bookmarks','homework','sql','preferences'];let total=0;for(const [area,entries] of Object.entries(backup.records)){if(!allowed.includes(area)||!entries||typeof entries!=='object'||Array.isArray(entries))throw Error('The backup contains an invalid record group.');records[area]={};for(const [key,v] of Object.entries(entries)){if(JSON.stringify(v).length>25000)throw Error('A saved item is too large.');const valid=area==='sql'?C.exercises.some(x=>x.id===key):area==='preferences'?key==='lastLesson':area==='homework'?['hw1','hw2','hw3'].includes(key):!!item(key)||(area==='notes'&&key==='general');if(!valid)throw Error('The backup contains an unknown course item.');let out;if(area==='notes'){if(typeof v!=='string')throw Error('A note is invalid.');out=v.slice(0,20000)}else if(area==='bookmarks'){if(typeof v!=='boolean')throw Error('A bookmark is invalid.');out=v}else if(area==='preferences'){if(!item(v))throw Error('A lesson preference is invalid.');out=v}else if(area==='homework'){out={};if(!v||typeof v!=='object')throw Error('A checklist is invalid.');for(const [n,on] of Object.entries(v)){if(!/^\d{1,2}$/.test(n)||typeof on!=='boolean')throw Error('A checklist item is invalid.');out[n]=on}}else{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('A saved activity is invalid.');out=area==='sql'?{query:typeof v.query==='string'?v.query.slice(0,20000):'',solved:v.solved===true,viewed:v.viewed===true}:{completed:v.completed===true,...(Number.isInteger(v.step)&&v.step>=0&&v.step<100?{step:v.step}:{}),...(['overview','steps','full','check'].includes(v.tab)?{tab:v.tab}:{}),...([0,1,2].includes(v.answer)?{answer:v.answer}:{})}}records[area][key]=out;total++}}stagedImport=records;modalOpen('Import your study backup',`<p>Import ${total} saved items into this browser. Items in the backup replace matching local items; other saved work stays in place.</p><div class="row"><button class="secondary" data-action="close">Cancel</button><button class="primary" data-action="confirm-import">Import backup</button></div>`)}catch(err){toast(err.message||'The backup could not be read.')}finally{e.target.value=''}});
document.addEventListener('keydown',e=>{if(e.target.id==='sql-editor'&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('[data-action=run-sql]').click()}if(e.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role=tab]'),n=tabs.indexOf(e.target);tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(n+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length].click()}});
window.addEventListener('hashchange',()=>{if(modal.open)modal.close();render(true)});
try{const raw=localStorage.getItem(storageKey)||localStorage.getItem('course-v2-guest');const stored=raw?JSON.parse(raw):null;if(stored?.records&&typeof stored.records==='object')state={records:stored.records}}catch{localAvailable=false}
$('#account-label').textContent='My learning';render();persist();
